const steps = ["charge", "reserve", "ship"];
const saga = { step: 2, status: "compensating" };

function resume(saga) {
  const log = [];
  if (saga.status === "running") {
    for (let i = saga.step; i < steps.length; i++) log.push(`run ${steps[i]}`);
  } else if (saga.status === "compensating") {
    for (let i = saga.step - 1; i >= 0; i--) log.push(`undo ${steps[i]}`);
  }
  return log.join(", ") || "nothing to do";
}

