function relay(outbox, publish) {
  let count = 0;
  const pending = outbox.filter((row) => !row.published).sort((a, b) => a.id - b.id);
  for (const row of pending) {
    try {
      publish(row);
    } catch {
      break;
    }
    row.published = true;
    count++;
  }
  return count;
}

