const stock = new Map([["lamp", 2]]);
const reservations = new Map();

function reserve(key, sku, quantity) {
  if (reservations.has(key)) return "already reserved";
  const available = stock.get(sku) ?? 0;
  if (available < quantity) throw new Error(`${sku} is out of stock`);
  stock.set(sku, available - quantity);
  reservations.set(key, { sku, quantity, status: "reserved" });
  return `reserved, ${available - quantity} left`;
}

