function check(runs) {
  let good = 0;
  for (const run of runs) {
    const confirmed = run.order === "confirmed" && run.payment === "captured" && run.shipment === "booked" && run.lampsAfter === run.lampsBefore - 1;
    const cancelled = run.order === "cancelled" && run.payment !== "captured" && run.shipment !== "booked" && run.lampsAfter === run.lampsBefore;
    if (confirmed || cancelled) good++;
    else console.log(`INCONSISTENT crash ${run.crashAt}`);
  }
  console.log(`${good} of ${runs.length} consistent`);
}

check([
  { crashAt: "after charge", order: "confirmed", payment: "captured", shipment: "booked", lampsBefore: 5, lampsAfter: 4 },
  { crashAt: "after reserve", order: "confirmed", payment: "captured", shipment: "booked", lampsBefore: 5, lampsAfter: 3 },
  { crashAt: "after undo reserve", order: "cancelled", payment: "refunded", shipment: "none", lampsBefore: 5, lampsAfter: 5 },
